"""Meridian CRM 4.2 EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP, localcontext


def _is_blank(value: object) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def _fixed(value: object, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: object, width: int) -> str:
    if _is_blank(value):
        amount = Decimal(0)
    elif isinstance(value, Decimal):
        amount = value
    else:
        amount = Decimal(str(value))

    digits = len(amount.as_tuple().digits)
    exponent = abs(amount.as_tuple().exponent)
    with localcontext() as context:
        context.prec = max(28, digits + exponent + 4)
        cents = int(
            (amount * Decimal(100)).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )
        )

    return f"{cents:0{width}d}"


def format_account(row: dict) -> str:
    """Return the 77-character EXPORT_ACCT record for one ACCT_MASTER row."""
    acct_id = row.get("ACCT_ID", "")
    acct_nm = row.get("ACCT_NM", "")
    region_cd = row.get("REGION_CD", "")
    ann_rev = row.get("ANN_REV", "")
    cred_hold = row.get("CRED_HOLD", "")
    create_dt = row.get("CREATE_DT", "")

    if _is_blank(cred_hold):
        cred_hold = "N"
    if _is_blank(create_dt):
        create_dt = "00000000"

    return (
        _fixed(acct_id, 10)
        + _fixed(acct_nm, 40)
        + _fixed(region_cd, 3)
        + _zpad_cents(ann_rev, 15)
        + str(cred_hold)
        + str(create_dt)
    )
